actions.script:
                String expires = ec.l10n.format(policy.expirationDate, 'dd/MM/yyyy')
                String firstName = (insured.name ?: '').tokenize(' ').with { it ? it[-1] : '' }
                String plate = policy.vehiclePlate ?: ''
                // the fixed template: also what test mode and a failing AI send
                messageText = language == 'vi'
                    ? "Chào ${firstName}, bảo hiểm TNDS xe ${plate} của bạn hết hạn ngày ${expires}. " +
                      "Gia hạn chỉ với một chạm: {link} . Cần hỗ trợ? Chọn 'Gọi cho tôi' trên trang. " +
                      "Trả lời DUNG để không nhận nhắc nhở. – ${agency.name}"
                    : "Hi ${firstName}, the compulsory insurance of ${plate} ends on ${expires}. " +
                      "Renew in one tap: {link} . Need help? Choose 'Call me' on the page. " +
                      "Reply STOP to receive no more reminders. – ${agency.name}"
                if (!'true'.equals(System.getenv('GROWERP_TEST_MODE'))) {
                    Map limits = [InchSms: 'at most 300 characters, plain text, no emoji',
                                  InchZalo: 'at most 450 characters, friendly, at most one emoji',
                                  InchVetc: 'at most 200 characters, a push notification title line and one sentence',
                                  InchEmail: 'at most 700 characters, two short paragraphs']
                    String prompt = """Write a renewal reminder for compulsory motor liability insurance (TNDS)
in ${new Locale(language).getDisplayLanguage(Locale.ENGLISH)}, for the ${channelEnumId - 'Inch'} channel, ${limits[channelEnumId] ?: 'short'}.
Facts (use only these): customer first name ${firstName}; licence plate ${plate}; vehicle ${policy.vehicleDescription ?: '-'};
insurer ${carrier.name}; cover ends ${expires}; sent by the agency ${agency.name}.
Rules: polite and calm; no urgency words, no countdowns, no threats about fines; no discounts, cashback,
gifts or prices; one clear next step: renew with one tap at the link written exactly as {link};
mention that the customer can ask for a call on that page; end with how to stop reminders
(reply ${language == 'vi' ? 'DUNG' : 'STOP'}). Return only the message text."""
                    try {
                        def GeminiAiUtil = ec.resource.script("component://growerp/service/GeminiAiUtil.groovy", null)
                        String text = GeminiAiUtil.callLlmApi(ec, prompt, [ownerPartyId: ownerPartyId,
                            temperature: 0.4, maxOutputTokens: 4096, purpose: 'insurance renewal reminder'])?.trim()
                        if (text && text.contains('{link}')) messageText = text
                    } catch (Throwable t) {
                        ec.logger.warn("Renewal reminder AI draft failed, template used: ${t.message}")
                        ec.message.clearErrors()
                    }
                }

service.description:
The customer's choice on the renewal page. confirm: the last 3 characters of
            the plate prove it is their vehicle; renew and callback need that confirmation;
            optout and sold stop all reminders. Staff are told by email.

actions.script:
import groovy.json.JsonOutput
import groovy.json.JsonSlurper
Map state = stateJson ? (new JsonSlurper().parseText(stateJson) as Map) : [:]
if (state.stage == 'end') { done = true; reply = ''; return }
ec.context.putAll([policy: items[0], text: text, state: state, language: language])
Map turn = ec.resource.script('component://growerp/service/insurance/voiceBot.groovy', null) as Map
reply = turn.reply
done = turn.done
outcomeEnumId = turn.outcomeEnumId
stateJson = JsonOutput.toJson(turn.state)
audio = null
if (speak && reply && !'true'.equals(System.getenv('GROWERP_TEST_MODE'))) {
    try {
        def GeminiAiUtil = ec.resource.script("component://growerp/service/GeminiAiUtil.groovy", null)
        byte[] pcm = GeminiAiUtil.callGeminiTts(ec,
                (language == 'en' ? 'Say warmly and clearly: ' : 'Nói bằng giọng ấm áp, rõ ràng: ') + reply,
                [ownerPartyId: items[0].ownerPartyId, purpose: 'insurance voice call',
                 model: System.getenv('GEMINI_TTS_MODEL') ?: 'gemini-2.5-flash-preview-tts'])
        // 16 bit little endian PCM, 24 kHz, mono -> wav
        def out = new ByteArrayOutputStream()
        def le = { int v, int n -> (0..<n).each { out.write((v >> (8 * it)) & 0xff) } }
        out.write('RIFF'.bytes); le(36 + pcm.length, 4); out.write('WAVEfmt '.bytes)
        le(16, 4); le(1, 2); le(1, 2); le(24000, 4); le(48000, 4); le(2, 2); le(16, 2)
        out.write('data'.bytes); le(pcm.length, 4); out.write(pcm)
        audio = out.toByteArray().encodeBase64().toString()
    } catch (Throwable t) {
        ec.logger.warn("Voice call speech failed, text only: ${t.message}")
        ec.message.clearErrors()
    }
}

def all = cand.candidates
def ids = all*.policyId
def touches = ids ? ec.entity.find('growerp.insurance.RenewalTouch')
        .condition('policyId', 'in', ids).list() : []
def byPolicy = touches.groupBy { it.policyId }
List steps = ['InevSent', 'InevOpened', 'InevVisited', 'InevConfirmed', 'InevRenewRequested', 'InevRenewed']
def reached = { List evs, String step ->
    // renewed by a call also counts as every step before it
    if (step == 'InevRenewed') return 'InevRenewed' in evs
    int idx = steps.indexOf(step)
    return evs.any { steps.indexOf(it) >= idx } || ('InevRenewed' in evs)
}
Map stages = [total: all.size()]
for (s in steps) stages[s] = all.count { reached((byPolicy[it.policyId] ?: [])*.eventEnumId, s) }
stages.InevCallback = all.count { 'InevCallback' in (byPolicy[it.policyId] ?: [])*.eventEnumId }
stages.InevOptOut = all.count { it.band == 'Stop' }
Map channels = [:]
for (ch in ['InchZalo', 'InchVetc', 'InchSms', 'InchEmail', 'InchVoiceBot', 'InchCall']) {
    def withCh = all.findAll { p -> (byPolicy[p.policyId] ?: []).any { it.channelEnumId == ch &&
            it.eventEnumId in ['InevSent', 'InevCalled'] || (ch == 'InchVoiceBot' && it.channelEnumId == ch) } }
    channels[ch] = [contacted: withCh.size(),
                    renewed: withCh.count { p -> reached((byPolicy[p.policyId] ?: [])*.eventEnumId, 'InevRenewRequested') }]
}
Map bands = ['High', 'Medium', 'Low', 'Done', 'Stop'].collectEntries { b -> [(b): all.count { it.band == b }] }
funnel = [stages: stages, channels: channels, bands: bands]
